head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


include("../js/PopupCalendar.js");
include("../js/libRoundPanel.js");
include("../js/list_common.js");
include("../js/bns_common.js");
include("../js/common.js");
include("../js/session.js");
include("../js/stf.js");
include("../js/utils.js");
scwin.vScrenID = "ULDBNS00000.gfm";
scwin.vMktactCd = "";
scwin.vBndApplId = "";
scwin.vBndListProcsTpCd = "1";
scwin.vRowCount = 0;
scwin.processGp;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vProcsStatCd;
scwin.vRegYn = 'N';
scwin.vRowPos = 0;
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_list_sync
 * 설명       : 신청/접수 목록을 조회한다.
 ***********************************************/
scwin.fn_list_sync = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    /*ORG SRC: grd_AcptList.ColumnProp("CHK", "headcheck") = false;*/
    X = false;
    var param = '';
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd; //시장조치코드
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == '1') {
        ShowWin(grd_ApplList);
    } else {
        ShowWin(grd_AcptList);
    }
};



/********************************************** 
 * 함수명   : fn_SetMktactCd
 * 설명       : 신규상장 채권시장조치구분코드를 설정한다.
 ***********************************************/
scwin.fn_SetMktactCd = function() {
    //숨기기
    showObj(label_47, false);
    showObj(cmb_MunibndTpCd, false);
    var screenId = InfoMenuID();

    //국채 개별상장 
    if (screenId == "BNS00000") {
        scwin.vMktactCd = "111";
        setObjectValue(cmb_BndTpCd, 'GB');
        cmb_BndTpCd.Enable2 = false;
    }
    //지방채
    else if (screenId == "BNS01000") {
        scwin.vMktactCd = "121";
        showObj(label_47, true);
        showObj(cmb_MunibndTpCd, true);
        setObjectValue(cmb_BndTpCd, 'MB');
        cmb_BndTpCd.Enable2 = false;
    }
    //특수채 개별상장
    else if (screenId == "BNS02000") {
        scwin.vMktactCd = "131";
        setObjectValue(cmb_BndTpCd, 'AB');
        cmb_BndTpCd.Enable2 = false;
    }
    //회사채 개별상장
    else if (screenId == "BNS03000") {
        scwin.vMktactCd = "141";
        setObjectValue(cmb_BndTpCd, 'CO');
        cmb_BndTpCd.Enable2 = false;
    }
    //외국채권 개별상장
    else if (screenId == "BNS04000") {
        scwin.vMktactCd = "151";
        setObjectValue(cmb_BndTpCd, 'FO');
        cmb_BndTpCd.Enable2 = false;
    }
};



/********************************************** 
 * 함수명   : fn_PresaleGovbndTrdTpCd
 * 설명       : 발행전국채거래구분코드를 설정한다.
 * jackal_150127
 ***********************************************/
scwin.fn_PresaleGovbndTrdTpCd = function() {
    var screenId = InfoMenuID();

    //국채 개별상장 
    if (screenId == "BNS00000") {
        cmb_PresaleGovbndTrdTpCd.Enable2 = true; // 국채만 수정가능 jackal_150127
    }
    //지방채
    else if (screenId == "BNS01000") {
        cmb_PresaleGovbndTrdTpCd.Enable2 = false; // 국채만 수정가능 jackal_150127
    }
    //특수채 개별상장
    else if (screenId == "BNS02000") {
        cmb_PresaleGovbndTrdTpCd.Enable2 = false; // 국채만 수정가능 jackal_150127
    }
    //회사채 개별상장
    else if (screenId == "BNS03000") {
        cmb_PresaleGovbndTrdTpCd.Enable2 = false; // 국채만 수정가능 jackal_150127
    }
    //외국채권 개별상장
    else if (screenId == "BNS04000") {
        cmb_PresaleGovbndTrdTpCd.Enable2 = false; // 국채만 수정가능 jackal_150127
    }
};



/********************************************** 
 * 함수명   : fn_dtl_sync
 * 설명       : 그리드 선택 시 상세내역을 조회한다.
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    //종목정보
    var dsNm = 'BNS_ISU_INFO';
    var qryId = 'lds.stf.bnscommon.select.readIsuInfo';
    fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param);

    //기준금리상세(표면이자율,발행가액)
    dsNm = 'BNS_COUPNRT_ISURPRC';
    qryId = 'lds.stf.bnscommon.select.readCoupnRtAndIsurPrc';
    fn_SearchBns(scwin.vScrenID, dts_CoupnRtAndIsurPrc, dsNm, qryId, param);

    //신용평가정보
    dsNm = 'BNS_CREDIT_INFO';
    qryId = 'lds.stf.bnscommon.select.listCredit';
    fn_SearchBns(scwin.vScrenID, dts_Credit, dsNm, qryId, param);

    //인수기관정보
    dsNm = 'BNS_UDWRT_INST';
    qryId = 'lds.stf.bnscommon.select.listUdwrtInst';
    fn_SearchBns(scwin.vScrenID, dts_UdwrtInst, dsNm, qryId, param);

    //원리금정보
    dsNm = 'BNS_PRINCINT_INFO';
    qryId = 'lds.stf.bnscommon.select.listPrincint';
    fn_SearchBns(scwin.vScrenID, dts_Princint, dsNm, qryId, param);

    //CALL
    dsNm = 'BNS_OPTION_CALL';
    qryId = 'lds.stf.bnscommon.select.listOptionCall';
    fn_SearchBns(scwin.vScrenID, dts_OptionCall, dsNm, qryId, param);

    //PUT
    dsNm = 'BNS_OPTION_PUT';
    qryId = 'lds.stf.bnscommon.select.listOptionPut';
    fn_SearchBns(scwin.vScrenID, dts_OptionPut, dsNm, qryId, param);

    //변동금리
    dsNm = 'BNS_CHG_INT';
    qryId = 'lds.stf.bnscommon.select.listChgInt';
    fn_SearchBns(scwin.vScrenID, dts_ChgInt, dsNm, qryId, param);

    //분할상환
    dsNm = 'BNS_SPLIT_REDMPT';
    qryId = 'lds.stf.bnscommon.select.listSplitRedmpt';
    fn_SearchBns(scwin.vScrenID, dts_SplitRedmpt, dsNm, qryId, param);

    //유동화자산
    dsNm = 'BNS_SECUTIZ_ASST';
    qryId = 'lds.stf.bnscommon.select.listSecutizAsst';
    fn_SearchBns(scwin.vScrenID, dts_SecutizAsst, dsNm, qryId, param);

    //주식관련 행사가격 조정 JACKAL_190220
    dsNm = 'BNS_STOCK_REL_EXECPRC_ADJ';
    qryId = 'lds.stf.bnscommon.select.listStockRelExerPrcAdj';
    fn_SearchBns(scwin.vScrenID, dts_StockRel, dsNm, qryId, param);
};




/********************************************** 
 * 함수명   : fn_SplitRedmptDdAutoCreate
 * 설명       : 분할상환일 자동생성.
 * JACKAL_190220
 ***********************************************/
scwin.fn_SplitRedmptDdAutoCreate = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vFstSplitRedmptDd = getObjectValue(edt_FstSplitRedmptDd);
    var vSplitRedmptCycle = getObjectValue(edt_SplitRedmptCycle);
    var vSplitRedmptMmendTpCd = getObjectValue(cmb_SplitRedmptMmendTpCd);
    var vEquivRedmptVal = getObjectValue(edt_EquivRedmptVal);
    var vSplitRedmptCnt = getObjectValue(edt_SplitRedmptCnt);
    param += "&{P}V_FST_SPLIT_REDMPT_DD=" + vFstSplitRedmptDd; //최초분할상환일자
    param += "&{P}V_SPLIT_REDMPT_CYCLE=" + vSplitRedmptCycle; //분할상환주기
    param += "&{P}V_SPLIT_REDMPT_MMEND_TP_CD=" + vSplitRedmptMmendTpCd; //분할상환월말구분코드
    param += "&{P}V_EQUIV_REDMPT_VAL=" + vEquivRedmptVal; //균등상환액
    param += "&{P}V_SPLIT_REDMPT_CNT=" + vSplitRedmptCnt; //분할상환횟수

    //분할상환
    dsNm = 'BNS_SPLIT_REDMPT';
    qryId = 'lds.stf.bnscommon.select.listSplitRedmptAutoCreate';
    fn_SearchBns(scwin.vScrenID, dts_SplitRedmpt, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_StockRelAutoInput
 * 설명       : 주식관련 행사가격 조정 자동생성.
 * JACKAL_190220
 ***********************************************/
scwin.fn_StockRelAutoInput = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vFstExerPrcAdjDd = getObjectValue(edt_FstExerPrcAdjDd);
    var vExerPrcAdjCycle = getObjectValue(edt_ExerPrcAdjCycle);
    var vStkcertMmendTpCd = getObjectValue(cmb_StkcertMmendTpCd);
    var vExerPrcAdjCnt = getObjectValue(edt_ExerPrcAdjCnt);
    param += "&{P}V_FST_EXER_PRC_ADJ_DD=" + vFstExerPrcAdjDd; //최초분할상환일자
    param += "&{P}V_EXER_PRC_ADJ_CYCLE=" + vExerPrcAdjCycle; //분할상환주기
    param += "&{P}V_STKCERT_MMEND_TP_CD=" + vStkcertMmendTpCd; //분할상환월말구분코드
    param += "&{P}V_EXER_PRC_ADJ_CNT=" + vExerPrcAdjCnt; //분할상환횟수

    //분할상환
    dsNm = 'BNS_STOCK_REL_EXECPRC_ADJ';
    qryId = 'lds.stf.bnscommon.select.listStockRelExerPrcAdjAutoInput';
    fn_SearchBns(scwin.vScrenID, dts_StockRel, dsNm, qryId, param);
};



/********************************************** 
 * 함수명   : fn_ChgIntRtAutoInput
 * 설명       : 변동금리 금리결정기준일 자동생성.
 * JACKAL_190509
 ***********************************************/
scwin.fn_ChgIntRtAutoInput = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vIsuDd = getObjectValue(edt_IsuDd);
    var vFstIntPayDd = getObjectValue(edt_FstIntPayDd);
    var vIntPayUnitMms = getObjectValue(edt_IntPayUnitMms);
    var vIntMmendTpCd = getObjectValue(cmb_IntMmendTpCd);
    var vIntPayCnt = getObjectValue(edt_IntPayCnt);
    var vIntDecsnBasDys = getObjectValue(edt_IntDecsnBasDys);
    param += "&{P}V_ISU_DD=" + vIsuDd; //발행일
    param += "&{P}V_FST_INT_PAY_DD=" + vFstIntPayDd; //최초이자지급일
    param += "&{P}V_INT_PAY_UNIT_MMS=" + vIntPayUnitMms; //이자지급주기
    param += "&{P}V_INT_MMEND_TP_CD=" + vIntMmendTpCd; //이자월말구분코드
    param += "&{P}V_INT_PAY_CNT=" + vIntPayCnt; //이자분할상환횟수
    param += "&{P}V_INT_DECSN_BAS_DYS=" + vIntDecsnBasDys; //금리결정기준일수

    //변동금리 
    dsNm = 'BNS_CHG_INT';
    qryId = 'lds.stf.bnscommon.select.listChgInt.Jikjun.AutoInput';
    vIntDecsnBasTpCd = getObjectValue(cmb_IntDecsnBasTpCd);
    if (vIntDecsnBasTpCd == '2') //  금일결정기준일 구분이 당해 이자지급일이면
        qryId = 'lds.stf.bnscommon.select.listChgInt.DangHae.AutoInput';
    fn_SearchBns(scwin.vScrenID, dts_ChgInt, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_CallOptionAutoCreate
 * 설명       : CALL_OPTION 행사일 자동생성.
 * JACKAL_190726
 ***********************************************/
scwin.fn_CallOptionAutoCreate = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vFstCallExerDd = getObjectValue(edt_FstCallExerDd);
    var vCallExerCycle = getObjectValue(edt_CallExerCycle);
    var vCallMmendTpCd = getObjectValue(cmb_CallMmendTpCd);
    var vCallExerCnt = getObjectValue(edt_CallExerCnt);
    param += "&{P}V_FST_CALL_EXER_DD=" + vFstCallExerDd; //최초분할상환일자
    param += "&{P}V_CALL_EXER_CYCLE=" + vCallExerCycle; //분할상환주기
    param += "&{P}V_CALL_MMEND_TP_CD=" + vCallMmendTpCd; //분할상환월말구분코드
    param += "&{P}V_CALL_EXER_CNT=" + vCallExerCnt; //분할상환횟수

    //옵션행사
    dsNm = 'BNS_OPTION_CALL';
    qryId = 'lds.stf.bnscommon.select.listCallOption.AutoCreate';
    fn_SearchBns(scwin.vScrenID, dts_OptionCall, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_PutOptionAutoCreate
 * 설명       : PUt_OPTION 행사일 자동생성.
 * JACKAL_190726
 ***********************************************/
scwin.fn_PutOptionAutoCreate = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vFstPutExerDd = getObjectValue(edt_FstPutExerDd);
    var vPutExerCycle = getObjectValue(edt_PutExerCycle);
    var vPutMmendTpCd = getObjectValue(cmb_PutMmendTpCd);
    var vPutExerCnt = getObjectValue(edt_PutExerCnt);
    param += "&{P}V_FST_PUT_EXER_DD=" + vFstPutExerDd; //최초분할상환일자
    param += "&{P}V_PUT_EXER_CYCLE=" + vPutExerCycle; //분할상환주기
    param += "&{P}V_PUT_MMEND_TP_CD=" + vPutMmendTpCd; //분할상환월말구분코드
    param += "&{P}V_PUT_EXER_CNT=" + vPutExerCnt; //분할상환횟수

    //옵션행사
    dsNm = 'BNS_OPTION_PUT';
    qryId = 'lds.stf.bnscommon.select.listPutOption.AutoCreate';
    fn_SearchBns(scwin.vScrenID, dts_OptionPut, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터를 정의한다.
 ***********************************************/
scwin.fn_SetComboCode = function() {
    //기관코드
    var qryId = 'lds.stf.bnscommon.select.listInstCd';
    var dsNm = 'BNS_INST_INFO';
    var param = '&{P}V_INST_NM=';
    fn_SearchBns(scwin.vScrenID, dts_InstCd, dsNm, qryId, param);
    fn_SetBnsCombo(scwin.vScrenID, dts_AsstHdTpCd, '03374'); //자산보유자 유형
    fn_SetBnsCombo(scwin.vScrenID, dts_SecutizAsstTpCd, '03375'); //유동화자산 유형
    fn_SetBnsCombo(scwin.vScrenID, dts_CoupntRtCd, '03050'); //표면이자율결정 기준금리

    fn_SetBnsCombo(scwin.vScrenID, dts_FrnBasIntTpCd1, '04764', false); //기준금리상세1
    fn_SetBnsCombo(scwin.vScrenID, dts_FrnBasIntTpCd2, '04768', false); //기준금리상세2
    fn_SetBnsCombo(scwin.vScrenID, dts_FrnBasIntTpCd3, '04766', false); //기준금리상세3
    fn_SetBnsCombo(scwin.vScrenID, dts_FrnBasIntTpCd4, '04767', false); //기준금리상세4

    //공통콤보
    var arrCid = [];
    arrCid.push({
        cid: '02475',
        cnm: 'cmb_CurrTpCd'
    }); //발행통화				
    arrCid.push({
        cid: '01422',
        cnm: 'cmb_BndTpCd'
    }); //채권유형				
    arrCid.push({
        cid: '03076',
        cnm: 'cmb_MunibndTpCd'
    }); //지방채구분				
    arrCid.push({
        cid: '03221',
        cnm: 'cmb_NusualBndTpCd'
    }); //특이채권유형			
    arrCid.push({
        cid: '03055',
        cnm: 'cmb_BndGuarTpCd'
    }); //보증/담보				
    arrCid.push({
        cid: '00872',
        cnm: 'cmb_IntPayMethdCd'
    }); //이자지급방법			
    arrCid.push({
        cid: '03075',
        cnm: 'cmb_AsstSecutizTpCd'
    }); //유동화					
    arrCid.push({
        cid: '03054',
        cnm: 'cmb_ImbdoptCorpbndCd'
    }); //옵션					
    arrCid.push({
        cid: '03563',
        cnm: 'cmb_CondCapSecuTpCd'
    }); //조건부자본증권유형		
    arrCid.push({
        cid: '03053',
        cnm: 'cmb_DebtRepayRankTpCd'
    }); //선/후/중순위			
    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyPrincPayDdDecsnCd'
    }); //휴무관련(원금)			
    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyDdIntPayMethdCd'
    }); //휴무관련(이자)			
    arrCid.push({
        cid: '01513',
        cnm: 'cmb_CoupnPayMethdCd'
    }); //이자 선/후급			
    arrCid.push({
        cid: '03195',
        cnm: 'cmb_BndIntPayDdBasTpCd'
