/********************************************** 
 * 함수명   : fn_MinusGumriOK
 * JACKAL_191129
 * 설명       : 개별 체크한다.
 ***********************************************/
scwin.fn_MinusGumriOK = function(obj, msg) {
    var obj_rt = getObjectValue(obj);
    if (obj_rt < 0) {
        if (!window.confirm('[' + msg + '] 마이너스(-) 값을 입력하셨습니다.\n이대로 처리하시겠습니까?')) {
            //setObjectValue(obj, obj_rt*(-1));
            obj.focus();
            return 1;
        }
    }
};





/********************************************** 
* 함수명   : fn_MinusGumriCheck
* JACKAL_191129
* 설명       : 개별 체크한다.
edt_CoupnRt COUPN_RT
edt_ScbdInt SCBD_INT
edt_BkHoldyDdPrincAcrintRt BK_HOLDY_DD_PRINC_ACRINT_RT
edt_BkHoldyDdIntCmpAcrintRt   BK_HOLDY_DD_INT_CMP_ACRINT_RT
edt_GrtYd GRT_YD
edt_AddYd ADD_YD
***********************************************/
scwin.fn_MinusGumriCheck = function() {
    if (!scwin.fn_MinusGumriOK(edt_CoupnRt, '표면이자율') &&
        !scwin.fn_MinusGumriOK(edt_ScbdInt, '낙찰금리') &&
        !scwin.fn_MinusGumriOK(edt_BkHoldyDdPrincAcrintRt, '휴무(원금)경과금리') &&
        !scwin.fn_MinusGumriOK(edt_BkHoldyDdIntCmpAcrintRt, '휴무(이자)경과금리') &&
        !scwin.fn_MinusGumriOK(edt_GrtYd, '보장수익률') &&
        !scwin.fn_MinusGumriOK(edt_AddYd, '추가수익률')) return 1;

    else return 0;
};


/********************************************** 
 * 함수명   : fn_CheckEach
 * 설명       : 개별 체크한다.
 ***********************************************/
scwin.fn_CheckEach = function() {
    //SRI채권 고유명 체크
    //if (! window.confirm('표면이자율이 미확정입니다.\n그래도 처리하시겠습니까?')) return 1;
    if (txb_sriBndTpCd.getValue() == '1') {
        //alert(txb_UnqIsuNm.value);
        if (txb_UnqIsuNm.getValue().indexOf("(녹)") == -1) {
            if (!window.confirm("ESG채권(녹색채권)으로 등록된 채권입니다.\n\n한글고유명에 '(녹)' 글자가 포함되어있지 않습니다.\n\n그래도 처리하시겠습니까?")) return 1;
        }
        if (txb_UnqIsuEngNm.getValue().indexOf("(G)") == -1) {
            if (!window.confirm("ESG채권(녹색채권)으로 등록된 채권입니다.\n\n영문고유명에 '(G)' 글자가 포함되어있지 않습니다.\n\n그래도 처리하시겠습니까?")) return 1;
        }
    } else if (txb_sriBndTpCd.getValue() == '2') {
        if (txb_UnqIsuNm.getValue().indexOf("(사)") == -1) {
            if (!window.confirm("ESG채권(사회적채권)으로 등록된 채권입니다.\n\n한글고유명에 '(사)' 글자가 포함되어있지 않습니다.\n\n그래도 처리하시겠습니까?")) return 1;
        }
        if (txb_UnqIsuEngNm.getValue().indexOf("(S)") == -1) {
            if (!window.confirm("ESG채권(사회적채권)으로 등록된 채권입니다.\n\n영문고유명에 '(S)' 글자가 포함되어있지 않습니다.\n\n그래도 처리하시겠습니까?")) return 1;
        }
    } else if (txb_sriBndTpCd.getValue() == '3') {
        if (txb_UnqIsuNm.getValue().indexOf("(지)") == -1) {
            if (!window.confirm("ESG채권(지속가능채권)으로 등록된 채권입니다.\n\n한글고유명에 '(지)' 글자가 포함되어있지 않습니다.\n\n그래도 처리하시겠습니까?")) return 1;
        }
        if (txb_UnqIsuEngNm.getValue().indexOf("(T)") == -1) {
            if (!window.confirm("ESG채권(지속가능채권)으로 등록된 채권입니다.\n\n영문고유명에 '(T)' 글자가 포함되어있지 않습니다.\n\n그래도 처리하시겠습니까?")) return 1;
        }
    } else if (txb_sriBndTpCd.getValue() == '4') {
        if (txb_UnqIsuNm.getValue().indexOf("(연)") == -1) {
            if (!window.confirm("ESG채권(지속가능연계채권)으로 등록된 채권입니다.\n\n한글고유명에 '(연)' 글자가 포함되어있지 않습니다.\n\n그래도 처리하시겠습니까?")) return 1;
        }
        if (txb_UnqIsuEngNm.getValue().indexOf("(L)") == -1) {
            if (!window.confirm("ESG채권(지속가능연계채권)으로 등록된 채권입니다.\n\n영문고유명에 '(L)' 글자가 포함되어있지 않습니다.\n\n그래도 처리하시겠습니까?")) return 1;
        }
    }


    //상장일이 발행일보다 빠른 경우 체크
    if (dts_IsuInfo.NameValue(1, "LIST_DD") < dts_IsuInfo.NameValue(1, "ISU_DD")) {
        if (!window.confirm('상장일이 발행일 이전입니다.\n그래도 처리하시겠습니까?')) return 1;
    }

    //수정 or 처리완료
    if (scwin.processGp == '3' || scwin.processGp == '4') {
        // 마이너스 금리 체크 (접수시는 값변경이 안됨)  수정 및 처리완료 시에만 체크하도록 수정
        if (!scwin.fn_MinusGumriCheck()) return 1; // JACKAL_191129

        //상환방법: 영구채 선택시 상환일: 9999-12-31 이여야함.
        if (getObjectValue(cmb_RedmptMethdTpCd) == "3" && getObjectValue(edt_RedmptDd) != "99991231") {
            alert("상환방법이 영구채 일 경우 상환일은 반드시 [9999-12-31]이여야 합니다.");
            edt_RedmptDd.focus();
            return 1;
        }
        // 상환일: 9999-12-31 선택시 상환방법: 영구채 이여야함.
        if (getObjectValue(edt_RedmptDd) == "99991231" && getObjectValue(cmb_RedmptMethdTpCd) != "3") {
            alert("상환일이 [9999-12-31] 일 경우 상환방법은 반드시 영구채이여야 합니다.");
            cmb_RedmptMethdTpCd.focus();
            return 1;
        }
        if (getObjectValue(cmb_RedmptMethdTpCd) == "3") {
            //상환방법: 영구채 선택시 비정기 선택해야 함. JACKAL_190509
            //if (getObjectValue(cmb_RedmptMethdTpCd) == "3" )
            //{
            //	var cd = getObjectValue(cmb_IntDecsnRegulYn);	
            //	// 금리결정 정기이면  
            //	if(cd == 'Y') 
            //	{
            //		alert("상환방법이 영구채 일 경우 변동금리 탭화면의 금리결정정기여부를 비정기로 선택하여야 합니다.");
            //		return 1;
            //	}
            //}

            if (!window.confirm("영구채로 처리하시겠습니까?")) {
                return 1;
            } else {
                return false;
            }
        }

        // 소액채권 표준코드와 상장시 표면이자율이 상이한지 체크 JACKAL_20.01.31
        var qryId111 = 'lds.stf.bnsnew.select.smallbndyn.coupnrt.stdcd';
        var dsNm111 = 'BNS_ISU_INFO';
        var param111 = '&{P}V_STD_CD=' + getObjectValue(txb_StdCd);
        dts_CheckCmData.SyncLoad = true;
        fn_SearchBns(scwin.vScrenID, dts_CheckCmData, dsNm111, qryId111, param111);
        if (dts_CheckCmData.CountRow > 0) {
            var cnt = dts_CheckCmData.NameValue(1, 'COUPN_RT');
            if (cnt != dts_IsuInfo.NameValue(1, "COUPN_RT")) {
                alert("표면이자율이 표준코드부여 시와 다릅니다.\n" + "관련 담당자에게 반드시 연락바랍니다.\n" + "연락 부재시 신고시장수익률 장애가 발생합니다.\n" + "[연락처]\n" + "KRX IT관리부 정보시스템팀 백윤경 과장(9875)\n" + "KRX IT관리부 증권시스템팀 김승한(9193)\n" + "코스콤 시장업무부 채권RDS 이승규 차장(676-8215)\n" + "코스콤 Check 송기성 과장(767-8621)");
                return 0;
            }
        }
    }

    //처리완료 시 체크
    if (scwin.processGp == '3') {
        //표면이자율 체크
        if (dts_IsuInfo.NameValue(1, "COUPN_RT_FINAL_YN") == '') {
            alert("표면이자율 확정여부를 선택하십시오.");
            return 1;
        } else if (dts_IsuInfo.NameValue(1, "COUPN_RT_FINAL_YN") == 'Y' &&
            dts_IsuInfo.NameValue(1, "COUPN_RT") == '') {
            alert("표면이자율 확정시에는 표면이자율을 입력하십시오.");
            return 1;
        } else if (dts_IsuInfo.NameValue(1, "COUPN_RT_FINAL_YN") == 'N' &&
            dts_IsuInfo.NameValue(1, "COUPN_RT") != '') {
            if (!window.confirm('표면이자율이 미확정입니다.\n그래도 처리하시겠습니까?')) return 1;
        }
    }

    //상환방법: 영구채 선택시 휴무관련(원금) : 해당없음 선택이 원칙이나 선택사항이므로 경고문구만 띄운다.
    if (getObjectValue(cmb_RedmptMethdTpCd) == "3" && getObjectValue(cmb_BkHoldyPrincPayDdDecsnCd) != "") {
        if (!window.confirm("상환방법이 '영구채'이며 휴무관련(원금)이 선택되었습니다.\n그래도 처리하시겠습니까?")) {
            return 1;
        } else {
            return 0;
        }
    }

    //이미 접수중인지 체크
    if (scwin.vBndListProcsTpCd == '1' &&
        getObjectValue(txb_StdCd) != '') {
        var qryId = 'lds.stf.bnsnew.select.listCheckNewListAcpt';
        var dsNm = 'BNS_CHECK_ITEM';
        var param = '&{P}V_STD_CD=' + getObjectValue(txb_StdCd);
        dts_CheckCmData.SyncLoad = true;
        fn_SearchBns(scwin.vScrenID, dts_CheckCmData, dsNm, qryId, param);
        if (dts_CheckCmData.CountRow > 0) {
            var id = dts_CheckCmData.NameValue(1, 'BND_APPL_ID');
            var dd = dts_CheckCmData.NameValue(1, 'STRT_DD');
            if (dts_CheckCmData.NameValue(1, 'APPL_YN') == 'Y') {
                alert("이미 접수번호 " + id + " : 적용일 " + dd + "로 시장조치되었습니다.");
                return 1;
            } else {
                alert("이미 접수번호 " + id + " : 적용일 " + dd + "로 처리중이므로 접수가 불가능합니다.");
                return 1;
            }
        }
    }
    if (scwin.vBndListProcsTpCd == '2') {
        //신용기관체크
        var creditMsg = '신용평가기관을 선택하지 않으셨습니다.';
        var creditMsg1 = '신용등급을 선택하지 않으셨습니다.';
        if (getObjectValue(cmb_CreditValuInstCd1) == '' &&
            getObjectValue(cmb_ByinstCreditValuGrd1) != '') {
            alert(creditMsg);
            cmb_CreditValuInstCd1.focus();
            return 1;
        } else if (getObjectValue(cmb_CreditValuInstCd1) != '' &&
            getObjectValue(cmb_ByinstCreditValuGrd1) == '') {
            alert(creditMsg1);
            cmb_ByinstCreditValuGrd1.focus();
            return 1;
        }
        if (getObjectValue(cmb_CreditValuInstCd2) == '' &&
            getObjectValue(cmb_ByinstCreditValuGrd2) != '') {
            alert(creditMsg);
            cmb_CreditValuInstCd2.focus();
            return 1;
        } else if (getObjectValue(cmb_CreditValuInstCd2) != '' &&
            getObjectValue(cmb_ByinstCreditValuGrd2) == '') {
            alert(creditMsg1);
            cmb_ByinstCreditValuGrd2.focus();
            return 1;
        }
        if (getObjectValue(cmb_CreditValuInstCd3) == '' &&
            getObjectValue(cmb_ByinstCreditValuGrd3) != '') {
            alert(creditMsg);
            cmb_CreditValuInstCd3.focus();
            return 1;
        } else if (getObjectValue(cmb_CreditValuInstCd3) != '' &&
            getObjectValue(cmb_ByinstCreditValuGrd3) == '') {
            alert(creditMsg1);
            cmb_ByinstCreditValuGrd3.focus();
            return 1;
        }
        if (getObjectValue(cmb_CreditValuInstCd4) == '' &&
            getObjectValue(cmb_ByinstCreditValuGrd4) != '') {
            alert(creditMsg);
            cmb_CreditValuInstCd4.focus();
            return 1;
        } else if (getObjectValue(cmb_CreditValuInstCd4) != '' &&
            getObjectValue(cmb_ByinstCreditValuGrd4) == '') {
            alert(creditMsg1);
            cmb_ByinstCreditValuGrd4.focus();
            return 1;
        }

        //발행용도 총계 체크
        var listAmt = getObjectValue(edt_ListAmt);
        if (getObjectValue(edt_EqmtFnd) != '' ||
            getObjectValue(edt_RefundFnd) != '' ||
            getObjectValue(edt_OperFnd) != '' ||
            getObjectValue(edt_MiscFnd) != '') {
            var eqmtAmt = getObjectValue(edt_EqmtFnd);
            if (eqmtAmt == '') eqmtAmt = 0;
            var refundAmt = getObjectValue(edt_RefundFnd);
            if (refundAmt == '') refundAmt = 0;
            var operAmt = getObjectValue(edt_OperFnd);
            if (operAmt == '') operAmt = 0;
            var miscAmt = getObjectValue(edt_MiscFnd);
            if (miscAmt == '') miscAmt = 0;
            var fndAmt = com.wconv.parseInt(eqmtAmt) + com.wconv.parseInt(refundAmt) + com.wconv.parseInt(operAmt) + com.wconv.parseInt(miscAmt);
            if (listAmt != fndAmt) {
                alert('발행용도 금액 총계를 확인하십시오.');
                tab_Detail.ActiveIndex = 1;
                if (getObjectValue(edt_EqmtFnd) != '') {
                    edt_EqmtFnd.Focus();
                    return 1;
                } else if (getObjectValue(edt_RefundFnd) != '') {
                    edt_RefundFnd.Focus();
                    return 1;
                } else if (getObjectValue(edt_OperFnd) != '') {
                    edt_OperFnd.Focus();
                    return 1;
                } else if (getObjectValue(edt_MiscFnd) != '') {
                    edt_MiscFnd.Focus();
                    return 1;
                }
            }
        }

        //인수기관체크
        var isHas = false;
        var udwrAmtMsg = '인수기관 금액을 입력하십시오.';
        var udwrInstMsg = '인수기관을 선택 하십시오.';
        var udwrt1 = getObjectValue(cmb_BndUdwrtInstCd1);
        var udwrt2 = getObjectValue(cmb_BndUdwrtInstCd2);
        var udwrt3 = getObjectValue(cmb_BndUdwrtInstCd3);
        var udwrt4 = getObjectValue(cmb_BndUdwrtInstCd4);
        var udwrt1Amt = 0;
        var udwrt2Amt = 0;
        var udwrt3Amt = 0;
        var udwrt4Amt = 0;
        var udwrt5Amt = 0;
        if (udwrt1 != '') {
            udwrt1Amt = getObjectValue(edt_UdwrtAmt1);
            if (udwrt2 == udwrt1) {
                isHas = true;
            } else if (udwrt3 == udwrt1) {
                isHas = true;
            } else if (udwrt4 == udwrt1) {
                isHas = true;
            }
            if (getObjectValue(edt_UdwrtAmt1) == '') {
                alert(udwrAmtMsg);
                edt_UdwrtAmt1.Focus();
                return 1;
            }
        } else {
            if (getObjectValue(edt_UdwrtAmt1) != '') {
                alert(udwrInstMsg);
                cmb_BndUdwrtInstCd1.Focus();
                return 1;
            }
        }
        if (udwrt2 != '') {
            udwrt2Amt = getObjectValue(edt_UdwrtAmt2);
            if (udwrt1 == udwrt2) {
                isHas = true;
            } else if (udwrt3 == udwrt2) {
                isHas = true;
            } else if (udwrt4 == udwrt2) {
                isHas = true;
            }
            if (getObjectValue(edt_UdwrtAmt2) == '') {
                alert(udwrAmtMsg);
                edt_UdwrtAmt2.Focus();
                return 1;
            }
        } else {
            if (getObjectValue(edt_UdwrtAmt2) != '') {
                alert(udwrInstMsg);
                cmb_BndUdwrtInstCd2.Focus();
                return 1;
            }
        }
        if (udwrt3 != '') {
            udwrt3Amt = getObjectValue(edt_UdwrtAmt3);
            if (udwrt1 == udwrt3) {
                isHas = true;
            } else if (udwrt2 == udwrt3) {
                isHas = true;
            } else if (udwrt4 == udwrt3) {
                isHas = true;
            }
            if (getObjectValue(edt_UdwrtAmt3) == '') {
                alert(udwrAmtMsg);
                edt_UdwrtAmt3.Focus();
                return 1;
            }
        } else {
            if (getObjectValue(edt_UdwrtAmt3) != '') {
                alert(udwrInstMsg);
                cmb_BndUdwrtInstCd3.Focus();
                return 1;
            }
        }
        if (udwrt4 != '') {
            udwrt4Amt = getObjectValue(edt_UdwrtAmt4);
            if (udwrt1 == udwrt4) {
                isHas = true;
            } else if (udwrt2 == udwrt4) {
                isHas = true;
            } else if (udwrt3 == udwrt4) {
                isHas = true;
            }
            if (getObjectValue(edt_UdwrtAmt4) == '') {
                alert(udwrAmtMsg);
                edt_UdwrtAmt4.Focus();
                return 1;
            }
        } else {
            if (getObjectValue(edt_UdwrtAmt4) != '') {
                alert(udwrInstMsg);
                cmb_BndUdwrtInstCd4.Focus();
                return 1;
            }
        }
        if (isHas) {
            alert('동일한 인수기관을 선택 하셨습니다. 인수기관을 확인하여 주십시요.');
            return 1;
        }

        //인수금액 총계 체크
        udwrt5Amt = getObjectValue(edt_UdwrtAmt5);
        if (udwrt5Amt == '') udwrt5Amt = 0;
        var udwrtAmt = com.wconv.parseInt(udwrt1Amt) + com.wconv.parseInt(udwrt2Amt) + com.wconv.parseInt(udwrt3Amt) + com.wconv.parseInt(udwrt4Amt) + com.wconv.parseInt(udwrt5Amt);
        if (udwrtAmt > 0) {
            if (listAmt != udwrtAmt) {
                alert('인수금액 총계를 확인하십시오.');
                tab_Detail.ActiveIndex = 2;
                if (getObjectValue(edt_UdwrtAmt1) != '') {
                    edt_UdwrtAmt1.Focus();
                    return 1;
                } else if (getObjectValue(edt_UdwrtAmt2) != '') {
                    edt_UdwrtAmt2.Focus();
                    return 1;
                } else if (getObjectValue(edt_UdwrtAmt3) != '') {
                    edt_UdwrtAmt3.Focus();
                    return 1;
                } else if (getObjectValue(edt_UdwrtAmt4) != '') {
                    edt_UdwrtAmt4.Focus();
                    return 1;
                } else if (getObjectValue(edt_UdwrtAmt5) != '') {
                    edt_UdwrtAmt5.Focus();
                    return 1;
                }
            }
        }

        //변동금리탭 이자율변경 정보
        var rowCnt = dts_ChgInt.CountRow;
        for (var idx = 1; idx <= rowCnt; idx++) {
            if (com.wconv.length(dts_ChgInt.NameValue(idx, 'INT_RT_CHG_DD')) != 8) {
                alert('변동금리탭 이자율결정 기준일 정보를 확인하여 주십시요.');
                dts_ChgInt.RowPosition = idx;
                return 1;
            }
        }

        //옵션탭 Call
        if (scwin.fn_chkCall() > 0) return 1;

        //옵션탭 Put
        if (scwin.fn_chkPut() > 0) return 1;

        //분할상환체크
        rowCnt = dts_SplitRedmpt.CountRow;
        for (var idx = 1; idx <= rowCnt; idx++) {
            if (com.wconv.length(dts_SplitRedmpt.NameValue(idx, 'INT_PAY_DD')) != 8) {
                alert('분할상환탭 불균등 정보를 확인하여 주십시요.');
                dts_SplitRedmpt.RowPosition = idx;
                return 1;
            }
        }

        //원리금정보
        rowCnt = dts_Princint.CountRow;
        for (var idx = 1; idx <= rowCnt; idx++) {
            if (com.wconv.length(dts_Princint.NameValue(idx, 'INT_PAY_DD')) != 8) {
                alert('원리금탭 정보를 확인하여 주십시요.');
                dts_Princint.RowPosition = idx;
                return 1;
            }
        }

        // 분리형BW여부가 체크가 안된 경우만 메세지 확인함. jackal_181210
        if (!chk_DetachBwYn.checked) {
            if (getObjectValue(cmb_StkRelCorpbndRghtTpCd) != '' &&
                getObjectValue(cmb_NusualBndTpCd) != '2') {
                msg = "" + "특이채권유형이 " + fn_getComboTextValue(cmb_NusualBndTpCd) + " 인데 " + "\n주식관련탭의 권리구분이 [" + fn_getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다." + "\n" + "\n주식관련탭의 권리구분은 주식관련사채일때만 입력가능한 항목입니다." + "\n그래도 작업을 계속하시겠습니까?";
                if (!window.confirm(msg)) return 1;
            }
        }

        //ELB등 
        if (getObjectValue(cmb_NusualBndTpCd) == '3' ||
            getObjectValue(cmb_NusualBndTpCd) == '4') {
            if (getObjectValue(edt_PrincGrtRt) == '') {
                alert("원금보장율을 입력하십시오.");
                return 1;
            }
        } else if (getObjectValue(edt_PrincGrtRt) == '') {
            if (getObjectValue(cmb_NusualBndTpCd) == '3' ||
                getObjectValue(cmb_NusualBndTpCd) == '4') {
                alert("ELB등 탭은 ELS/DLS채권시에만 입력합니다. 특이채권유형을 확인바랍니다.");
                return 1;
            }
        }
        if (dts_IsuInfo.NameValue(1, "INT_PAY_METHD_CD") == '' ||
            dts_IsuInfo.NameValue(1, "INT_PAY_METHD_CD").substring(0, 1) == '1') {
            if (dts_IsuInfo.NameValue(1, "INT_RT_DECSN_MISC_BAS_INT_NM") != '') {
                alert("변동금리탭은 변동금리시에만 입력합니다. 이자지급방법을 확인바랍니다.");
                return 1;
            }
        }
        if (dts_IsuInfo.NameValue(1, "IMBDOPT_CORPBND_CD") == '' &&
            (dts_OptionCall.CountRow > 0 || dts_OptionPut.CountRow > 0)) {
            alert("CALL/PUT 탭은 옵션일 경우에만 입력합니다. 옵션구분을 확인바랍니다.");
            return 1;
        }
        if (dts_IsuInfo.NameValue(1, "ASST_SECUTIZ_TP_CD") == '' &&
            dts_IsuInfo.NameValue(1, "SECUTIZ_ADM_INST_CD").substring(0, 1) == '1') {
            alert("유동화탭은 유동화 채권일 경우에만 입력합니다. 유동화채권 인지 확인바랍니다.");
            return 1;
        }
        if (!checkMaxLength(txb_IntRtDecsnMiscBasIntNm, 20, '기타기준금리')) return 1;
        if (!checkMaxLength(txb_NusualIsuCondContn, 60, '특이발행조건(외부용)')) return 1;
        if (!checkMaxLength(txb_MemoContn, 200, '기타참고사항(내부용)')) return 1;
        if (!checkMaxLength(txb_UlyContn, 100, '기초자산상세내용')) return 1;
        if (!checkMaxLength(txb_ElsCondContn1, 100, '조건내용1')) return 1;
        if (!checkMaxLength(txb_ElsCondContn2, 100, '조건내용2')) return 1;

        // jackal_16.10.11  call put 사유 길이 체크 추가
        if (!checkMaxLength(txb_CallExerRsn, 50, '콜 사유')) return 1;
        if (!checkMaxLength(txb_PutExerRsn, 50, '풋 사유')) return 1;

        //국고채만 스트립미분리잔액 입력가능
        if (scwin.vMktactCd == '111' &&
            getObjectValue(cmb_InfllnkYn) != 'Y' &&
            dts_IsuInfo.NameValue(1, "ISU_NM").indexOf("변동") == -1) {
            if (dts_IsuInfo.NameValue(1, "ISUR_CD") == 'GB035' &&
                getObjectValue(cmb_BndStripTpCd) == '1') {
                var num_iss_dt = getObjectValue(edt_IsuDd);
                var expr_term = (getObjectValue(edt_RedmptDd) - getObjectValue(edt_IsuDd)) / 10000;

                // 2006년 이후 발행된 만기 5년이상 국고채권만 미분류 잔액이 존재
                // jackal_150714 3년물이상으로 변경되었는데 여태 수정이 안되어 있었슴. expr_term 5을 3을 수정
                if (num_iss_dt >= 20060101 && expr_term >= 3) {
                    alert('스트립미분리잔액을 상장금액으로 자동설정합니다.');
                    setObjectValue(edt_StripNsprtBal, getObjectValue(edt_ListAmt));
                } else {
                    setObjectValue(edt_StripNsprtBal, '');
                }
            }
        } else {
            setObjectValue(edt_StripNsprtBal, '');
        }

        //환율적용 발행금액,상장금액 체크
        if (getObjectValue(cmb_CurrTpCd) != '' &&
            getObjectValue(cmb_CurrTpCd) != '1') {
            var isuAmt = getObjectValue(edt_IsuAmt);
            var listAmt = getObjectValue(edt_ListAmt);
            if (isuAmt == '') isuAmt = 0;
            if (listAmt == '') listAmt = 0;
            var exchrt = fn_SearchExchrt(scwin.vScrenID, dts_CheckExa, getObjectValue(cmb_CurrTpCd), '1');
            isuAmt = isuAmt * exchrt;
            listAmt = listAmt * exchrt;

            //메시지 추가 발행금액이 상장금액보다 크거나 같아야 합니다.
            if (com.wconv.parseInt(isuAmt) < com.wconv.parseInt(listAmt)) {
                alert("발행금액은 상장금액보다 크거나 같아야 합니다.");
                return 1;
            }
            if (isuAmt <= 100000000) {
                alert("발행금액이 1억원 이하입니다.");
            } else if (isuAmt >= 1000000000000) {
                alert("발행금액이 1조원 이상입니다.");
            }
            if (listAmt <= 100000000) {
                alert("상장금액이 1억원 이하입니다.");
            } else if (listAmt >= 1000000000000) {
                alert("상장금액이 1조원 이상입니다.");
            }
        }

        // 분리형BW여부가 체크는 특이채권유형이 일반채권인 경우만 체크가능 jackal_181210
        if (chk_DetachBwYn.checked) {
            if (getObjectValue(cmb_NusualBndTpCd) != '1') {
                msg = "" + "분리형BW가 체크된 경우 특이채권유형이 [1 일반채권] 이어야 합니다." + "\n특이채권유형이 [" + fn_getComboTextValue(cmb_NusualBndTpCd) + "]로 입력되어 있습니다.";
                alert(msg);
                return 1;
            }
        }


        //  분리형BW여부가 체크되어 있스면 권리구분이 21 이어야 하고 jackal_181210
        if (chk_DetachBwYn.checked) {
            // 주식관련 권리구분 21 setting
            if (getObjectValue(cmb_StkRelCorpbndRghtTpCd) != '21') {
                msg = "" + "분리형BW가 체크된 경우 주식관련탭의 권리구분이 [21 신주인수권(분리형)] 이어야 합니다. " + "\n주식관련탭의 권리구분이 [" + fn_getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다.";
                alert(msg);
                return 1;
            }
        }

        // 더불어 특이채권유형이 2(주권관련채권) 이면 21은 선택 못하게 해야 함. jackal_181210
        if (getObjectValue(cmb_NusualBndTpCd) == '2') {
            if (getObjectValue(cmb_StkRelCorpbndRghtTpCd) == '21') {
                msg = "" + "특이채권유형이 " + fn_getComboTextValue(cmb_NusualBndTpCd) + " 인데 " + "\n주식관련탭의 권리구분이 [" + fn_getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다." + "\n" + "\n이 권리구분은 일반채권 분리형BW가 체크 되었을때만 입력가능한 항목입니다.";
                alert(msg);
                return 1;
            }
        }

        //이자지급방법이 변동금리형이면
        if (getObjectValue(cmb_IntPayMethdCd) > 20) {
            // 금리결정기준일 1~10 일까지 만 입력 체크   JACKAL_190509
            var vIntDecsnBasDys = getObjectValue(edt_IntDecsnBasDys);
            if (vIntDecsnBasDys != '' && (vIntDecsnBasDys > 10 || vIntDecsnBasDys < 1)) {
                if (!window.confirm('변동금리 탭의 이자지급기준일로부터 금리결정기준일은 1 ~ 10 일전 까지만 선택가능합니다.\n그래도 처리하시겠습니까?')) return 1;
            }
        }
    }
    return 0;
};



/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //종목정보체크
    if (fn_CheckNewListIsuInfo(dts_IsuInfo) > 0) return;
    if (scwin.fn_CheckEach() > 0) return;
    if (scwin.processGp == '4') {
        if (fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.vBndApplId) > 0) return;
    }
    //채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if (fn_ChkBndClssAndIsur(scwin.vScrenID, dts_IsuInfo, scwin.vMktactCd) > 0) return;

    //고객요건에의한 체크 추가. 2024-06-05 by김효준
    if (fn_AddCheck() > 0) return;

    //수수료체크
    if (fn_CheckFee(scwin.vScrenID, '1', dts_CheckCmData, scwin.vBndApplId) > 0) return;
    //처리완료,수정
    var hasAttachDoc = dts_IsuInfo.NameValue(1, "HAS_ATTACH_DOC");
    if (scwin.processGp == '4') {
        //if(! fn_EndConfirm(hasAttachDoc, '수정')) return;		
        if (!fn_EndConfirm1(scwin.vScrenID, dts_Temp, scwin.vBndApplId, scwin.vBndListProcsTpCd, '수정')) return;
    } else {
        //적용일,매매일,마감일,채권마감 체크
        if (fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, getObjectValue(edt_ListDd), scwin.vBndApplId) > 0) return;
        //if(! fn_EndConfirm(hasAttachDoc, '처리완료')) return;				
        if (!fn_EndConfirm1(scwin.vScrenID, dts_Temp, scwin.vBndApplId, scwin.vBndListProcsTpCd, '처리완료')) return;
    }

    //발행방법설정

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    var ISU_METHD_INDIRECT = dts_IsuInfo.NameValue(1, 'ISU_METHD_INDIRECT');
    var ISU_METHD_DIRECT = dts_IsuInfo.NameValue(1, 'ISU_METHD_DIRECT');
    var ISU_METHD_PPBOND = dts_IsuInfo.NameValue(1, 'ISU_METHD_PPBOND'); /*ORG SRC: dts_IsuInfo.NameValue(1, 'BND_ISU_METHD_CD') = ISU_METHD_INDIRECT + '' + ISU_METHD_DIRECT + '' + ISU_METHD_PPBOND*/ X = ISU_METHD_INDIRECT + '' + ISU_METHD_DIRECT + '' + ISU_METHD_PPBOND;

    // 분리형BW여부 설정 jackal_181210

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    var DETACH_BW_YN = dts_IsuInfo.NameValue(1, 'DETACH_BW_YN');
    if (DETACH_BW_YN == '1') /*ORG SRC: dts_IsuInfo.NameValue(1, 'DETACH_BW_YN') = 'Y'*/ X = 'Y';


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    else /*ORG SRC: dts_IsuInfo.NameValue(1, 'DETACH_BW_YN') = 'N'*/ X = 'N';

    //탭 데이터셋 설정
    scwin.fn_SetCreditData();
    scwin.fn_SetUdwrtInstData();
    scwin.fn_SetSecutizAsstData();
    scwin.fn_SetBasIntRtData();

    //변경된 데이터가 없더라도 데이터셋 전송하여 처리완료 진행
    dts_IsuInfo.UseChangeInfo = "False";
    dts_OptionCall.UseChangeInfo = "False";
    dts_OptionPut.UseChangeInfo = "False";
    dts_Princint.UseChangeInfo = "False";
    dts_SplitRedmpt.UseChangeInfo = "False";
    dts_ChgInt.UseChangeInfo = "False";
    // 주식관련 행사가격 조정 JACKAL_190220
    dts_StockRel.UseChangeInfo = "False";
    var url = "/bns/NewList.do?method=processAcptProcessComplt";
    if (scwin.processGp == '4') {
        url = "/bns/NewList.do?method=updateAcpt";

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "BND_APPL_ID=" + scwin.vBndApplId;
    param += ", BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    param += ", STRT_DD=" + dts_IsuInfo.NameValue(1, "LIST_DD");
    param += ", STD_CD=" + dts_IsuInfo.NameValue(1, "STD_CD"); /*ORG SRC: dts_IsuInfo.NameValue(1, 'COUPN_RT_DECSN_BAS_INT_CD') = getObjectValue(cmb_CoupnRtDecsnBasIntCd);*/ X = getObjectValue(cmb_CoupnRtDecsnBasIntCd);
    var dsKeyValue = "JSP(";
    dsKeyValue += "I:pInput=dts_IsuInfo";
    dsKeyValue += ", I:pInput1=dts_Credit";
    dsKeyValue += ", I:pInput2=dts_UdwrtInst";
    dsKeyValue += ", I:pInput3=dts_CoupnRtAndIsurPrc";
    dsKeyValue += ", I:pInput4=dts_Princint";
    dsKeyValue += ", I:pInput5=dts_OptionCall";
    dsKeyValue += ", I:pInput6=dts_OptionPut";
    dsKeyValue += ", I:pInput7=dts_ChgInt";
    dsKeyValue += ", I:pInput8=dts_SplitRedmpt";
    dsKeyValue += ", I:pInput9=dts_SecutizAsst";
    dsKeyValue += ", I:pInput10=dts_StockRel"; // 주식관련 행사가격조정 JACKAL_190220

    dsKeyValue += ")";
    trs_Save.Action = fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = dsKeyValue;
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SetCreditData
 * 설명       : 신용평가 데이터셋 설정
 ***********************************************/
scwin.fn_SetCreditData = function() {
    dts_Credit.ClearData();
    if (getObjectValue(cmb_CreditValuInstCd1) != '') {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
