        dts_SecutizAsst.insertRow(); /*ORG SRC: dts_SecutizAsst.NameValue(dts_SecutizAsst.RowPosition, 'BND_APPL_ID') = vBndApplId;*/ X = scwin.vBndApplId; /*ORG SRC: dts_SecutizAsst.NameValue(dts_SecutizAsst.RowPosition, 'BND_LIST_PROCS_TP_CD') = vBndListProcsTpCd;*/ X = scwin.vBndListProcsTpCd; /*ORG SRC: dts_SecutizAsst.NameValue(dts_SecutizAsst.RowPosition, 'HD_ASST_ORD') = '4';*/ X = '4'; /*ORG SRC: dts_SecutizAsst.NameValue(dts_SecutizAsst.RowPosition, 'ASST_HD_INST_CD') = 'ZZZZZ';*/ X = 'ZZZZZ'; /*ORG SRC: dts_SecutizAsst.NameValue(dts_SecutizAsst.RowPosition, 'ASST_HD_INST_MISC_CONTN') = getObjectValue(txb_AsstHdInstMiscContn);*/ X = getObjectValue(txb_AsstHdInstMiscContn); /*ORG SRC: dts_SecutizAsst.NameValue(dts_SecutizAsst.RowPosition, 'ASST_HD_TP_MISC_CONTN') = getObjectValue(txb_AsstHdTpMiscContn);*/ X = getObjectValue(txb_AsstHdTpMiscContn); /*ORG SRC: dts_SecutizAsst.NameValue(dts_SecutizAsst.RowPosition, 'ASST_ADM_INST_MISC_CONTN') = getObjectValue(txb_AsstAdmInstMiscContn);*/ X = getObjectValue(txb_AsstAdmInstMiscContn); /*ORG SRC: dts_SecutizAsst.NameValue(dts_SecutizAsst.RowPosition, 'SECUTIZ_ASST_TP_MISC_CONTN') = getObjectValue(txb_SecutizAsstTpMiscContn);*/ X = getObjectValue(txb_SecutizAsstTpMiscContn);
    }
