/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //종목정보체크
    if (fn_CheckNewListIsuInfo(dts_IsuInfo) > 0) return;
    if (scwin.fn_CheckEach() > 0) return;
    //적용일,매매일,마감일,채권마감 체크
    if (fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, getObjectValue(edt_ListDd), scwin.vBndApplId) > 0) return;
    //채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if (fn_ChkBndClssAndIsur1(scwin.vScrenID, dts_IsuInfo, scwin.vMktactCd) > 0) return;

    //고객요건에의한 체크 추가. 2024-06-05 by김효준
    if (fn_AddCheck() > 0) return;

    //접수
    var hasAttachDoc = dts_IsuInfo.NameValue(1, "HAS_ATTACH_DOC");
    //if(! fn_EndConfirm(hasAttachDoc, '접수')) return;
    if (!fn_EndConfirm1(scwin.vScrenID, dts_Temp, scwin.vBndApplId, scwin.vBndListProcsTpCd, '접수')) return;

    //수수료 팝업호출
    scwin.fn_GetPar = fn_GetParNewListFee;
    scwin.fn_SetPar = fn_SetParNewListFee;
    fn_PopNewListFee(grd_ApplList);
    if (scwin.vRegYn != "Y") return;

    //변경된 데이터가 없더라도 데이터셋 전송하여 처리 진행

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    dts_Fee.UseChangeInfo = "False";
    var url = "/bns/NewList.do?method=processAcpt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "BND_APPL_ID=" + scwin.vBndApplId;
    param += ", BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    param += ", STRT_DD=" + dts_IsuInfo.NameValue(1, "LIST_DD"); /*ORG SRC: dts_IsuInfo.NameValue(1, 'COUPN_RT_DECSN_BAS_INT_CD') = getObjectValue(cmb_CoupnRtDecsnBasIntCd);*/ X = getObjectValue(cmb_CoupnRtDecsnBasIntCd);
    trs_Save.Action = fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuInfo, I:pInput1=dts_Fee)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};



