/********************************************** 
 * 함수명   : fn_ExcelDownload
 * 설명       : 엑셀다운로드
 ***********************************************/
scwin.fn_ExcelDownload = function() {
    if (scwin.vRowCount == 0) return;
    showload.style.display = "";

    // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리
    btn_Excel.setDisabled(false);
    btn_Excel.src = "../img/btn_excelsave_d.gif";
    var param = '';
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd; //시장조치코드
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var dsNm = 'BNS_APPL_ACPT_LIST_EXCEL';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt.excel';
    fn_SearchBns(scwin.vScrenID, dts_List_excel, dsNm, qryId, param);
    ShowWin(grd_Grid_excel);
};


/********************************************** 
 * 함수명   : fn_DataVerification
 * 설명       : 데이터검증버튼 클릭 시 -> 엑셀 다운로드
 ***********************************************/
scwin.fn_DataVerification = function() {
    if (dts_List.CountRow == 0) {
        alert("데이터가 없습니다.");
        return;
    }
    if (!window.confirm("엑셀로 다운로드하시겠습니까?")) {
        return;
    }
    var param = '';
    var dsNm = 'BNS_APPL_ACPT_LIST_DATA_VF';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt.dataVerification';
    fn_SearchBns(scwin.vScrenID, dts_DataVf, dsNm, qryId, param);
};


/**
 * 기준금리상세 첫번째 콤보 onChange
 */
scwin.fn_CtrlFrnBasIntTpCd1 = function() {
    // 콤보 데이터 필터링
    scwin.fn_FilterComboValue();

    // 콤보 활성비활성, 보이고 안보이고 세팅
    if (tab_List.ActiveIndex == 1) {
        scwin.fn_CtrlObject1_1();
    } else {
        scwin.fn_CtrlObject1_2();
    }
};



/**
 * 기준금리상세 세번째 콤보 onChange
 *    - 기타상세 항목 활성/비활성
 */
scwin.fn_CtrlFrnBasIntTpCd3 = function() {
    var frnBasIntTpCd3 = getObjectValue(cmb_FrnBasIntTpCd3);
    // 콤보3의 기타 -- 상세입력만 활성
    if (frnBasIntTpCd3 == "2Z" || frnBasIntTpCd3 == "3Z" || frnBasIntTpCd3 == "4Z" || frnBasIntTpCd3 == "5Z") {
        txb_FrnBasIntMisc.setDisabled(true);
    } else {
        txb_FrnBasIntMisc.setDisabled(false); //기타는 기본값 비활성
    }
};



/**
 * 기준금리 2~4번째 콤보 필터링
 */
scwin.fn_FilterComboValue = function() {
    var frnBasIntTpCd1 = getObjectValue(cmb_FrnBasIntTpCd1);
    dts_FrnBasIntTpCd2.Filter();
    dts_FrnBasIntTpCd3.Filter();
    dts_FrnBasIntTpCd4.Filter();

    // 관련 항목 기본값 세팅
    cmb_FrnBasIntTpCd2.Index = 0;
    cmb_FrnBasIntTpCd3.Index = 0;
    cmb_FrnBasIntTpCd4.Index = 0;
};


/**
 * 신청내역 탭에서 기준금리상세 항목 컨트롤
 * 신청내역 탭에서는 전부 비활성...
 */
scwin.fn_CtrlObject1_1 = function() {
    var frnBasIntTpCd1 = getObjectValue(cmb_FrnBasIntTpCd1);

    // 일단 전부 활성화
    cmb_FrnBasIntTpCd2.Enable2 = false;
    cmb_FrnBasIntTpCd3.Enable2 = false;
    cmb_FrnBasIntTpCd4.Enable2 = false;
    txb_FrnBasIntMisc.setDisabled(false); //기타 비활성

    showObj(cmb_FrnBasIntTpCd2, true);
    showObj(txb_FrnBasIntTp2, false);
    showObj(img_isurCd, false);

    // 시가평가수익률(발행기관), 콤보2 안보이고 발행기관입력팝업 보이고..
    if (frnBasIntTpCd1 == "4") {
        showObj(cmb_FrnBasIntTpCd2, false);
        showObj(txb_FrnBasIntTp2, true);
    }
};



/**
 * 접수내역 탭에서 기준금리상세 항목 컨트롤
 */
scwin.fn_CtrlObject1_2 = function() {
    var frnBasIntTpCd1 = getObjectValue(cmb_FrnBasIntTpCd1);

    // 일단 전부 활성화
    cmb_FrnBasIntTpCd2.Enable2 = true;
    cmb_FrnBasIntTpCd3.Enable2 = true;
    cmb_FrnBasIntTpCd4.Enable2 = true;
    //txb_FrnBasIntMisc.disabled = true;  //기타는 비활성

    showObj(cmb_FrnBasIntTpCd2, true);
    showObj(txb_FrnBasIntTp2, false);
    showObj(img_isurCd, false);

    // 최종호가수익률
    if (frnBasIntTpCd1 == "1") {
        cmb_FrnBasIntTpCd4.Enable2 = false;

        // 시가평가수익률(CD/CP), 시가평가수익률(채권그룹), 워노하이자율스왑
    } else if (frnBasIntTpCd1 == "2" || frnBasIntTpCd1 == "3" || frnBasIntTpCd1 == "5") {
        // nothing to do


        // 시가평가수익률(발행기관), 콤보2 안보이고 발행기관입력팝업 보이고..

    } else if (frnBasIntTpCd1 == "4") {
        showObj(cmb_FrnBasIntTpCd2, false);
        showObj(txb_FrnBasIntTp2, true);
        showObj(img_isurCd, true);

        // KOFR금리 -- 전부 비활성
    } else if (frnBasIntTpCd1 == "6") {
        cmb_FrnBasIntTpCd2.Enable2 = false;
        cmb_FrnBasIntTpCd3.Enable2 = false;
        cmb_FrnBasIntTpCd4.Enable2 = false;

        // 기타 -- 상세입력빼고 전부 비활성
    } else if (frnBasIntTpCd1 == "7") {
        cmb_FrnBasIntTpCd2.Enable2 = false;
        cmb_FrnBasIntTpCd3.Enable2 = false;
        cmb_FrnBasIntTpCd4.Enable2 = false;
        txb_FrnBasIntMisc.setDisabled(true); // 상세입력만 활성
    }
};



/********************************************** 
 * 함수명   : fn_ShowIsurPopup
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsurPopup = function(obj) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    fn_PopIsurSearch(obj);
};

/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: getObjectValue(txb_FrnBasIntTpCd2),
        ISUR_NM: getObjectValue(txb_FrnBasIntTp2)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
