 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    setObjectValue(txb_FrnBasIntTpCd2, arrPar[0].ISUR_CD);
    setObjectValue(txb_FrnBasIntTp2, arrPar[0].ISUR_NM);
};
scwin.gform_onload = function() {
    //숨기기
    showObj(lbl_ReturnPos, false);
