    showObj(grd_DataVf, false);
    showload.style.display = "none";
    showObj(txb_sriBndApplTpCd, false);
    showObj(txb_sriBndTpCd, false);
    showObj(txb_sriBndRcptYn, false);
    showObj(txb_FrnBasIntTpCd2, false);

    // 행사종료일 숨기기 JACKAL_190726
    //fn_option_exer_Init();

    //탭지정
    tab_List.ActiveIndex = 1;
    tab_Detail.ActiveIndex = 1;
    tab_SecutizAsst.ActiveIndex = 1;

    //패널라운드처리
    BnsPanelToGroupBox(pnl_IsuInfo);
    BnsPanelToGroupBox(pnl_IsurCond);
    BnsPanelToGroupBox(pnl_RelInst);
    BnsPanelToGroupBox(pnl_CoupnRt);
    BnsPanelToGroupBox(pnl_IsurPrc);
    BnsPanelToGroupBox(pnl_StockRel);
    BnsPanelToGroupBox(pnl_Princint);
    BnsPanelToGroupBox(pnl_Option);
    BnsPanelToGroupBox(pnl_ChgInt);
    BnsPanelToGroupBox(pnl_SplitRedmpt);
    //유동화
    BnsPanelToGroupBox(pnl_SecutizAsst);
    BnsPanelToGroupBox(pnl_SecutizRelInst);
    BnsPanelToGroupBox(pnl_SecutizAsstMisc);
    //스트립
    BnsPanelToGroupBox(pnl_Strip);
    BnsPanelToGroupBox(pnl_Els);

    //콤보설정
    scwin.fn_SetComboCode();
    //시장조치구분 설정
    scwin.fn_SetMktactCd();
    //탭설정
    scwin.fn_SetDtlTab();
    //목록조회
    scwin.fn_list_sync();

    //임시데이터셋설정
    dts_Temp.SetDataHeader("TEMP:String");
    dts_Temp.insertRow();
    txb_BndTpNm.style.backgroundColor = "#ffffff";
    cmb_BndIntPayDdBasTpCd.style.backgroundColor = "#ffffff";
    cmb_IntMmendTpCd.style.backgroundColor = "#ffffff";

    // 데이터검증 버튼 초기화 - 회사채인경우만 보임.
    if (scwin.vMktactCd == "141") {
        showObj(btn_data_vf, true);
        btn_data_vf.style.top = "217";
    } else {
        showObj(btn_data_vf, false);
    }
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vRowCount = 0;
    scwin.fn_ClearIsuInfo();
    scwin.vBndListProcsTpCd = nIndex;
    showObj(txb_Dtl1, false);
    showObj(txb_Dtl, true);
    if (scwin.vBndListProcsTpCd == 2) {
        txb_Dtl.setValue("접수내역");
        txb_BndTpNm.style.backgroundColor = "#ffff99";
        cmb_BndIntPayDdBasTpCd.style.backgroundColor = "#ffff99";
        cmb_IntMmendTpCd.style.backgroundColor = "#ffff99";
        showObj(btn_Excel, true);

        // 데이터검증 버튼 안보이게.
        showObj(btn_data_vf, false);
    } else {
        txb_Dtl.setValue("신청내역");
        txb_BndTpNm.style.backgroundColor = "#ffffff";
        cmb_BndIntPayDdBasTpCd.style.backgroundColor = "#ffffff";
        cmb_IntMmendTpCd.style.backgroundColor = "#ffffff";
        showObj(btn_Excel, false);

        // 데이터검증 버튼 초기화 - 회사채인경우만 보임.
        if (scwin.vMktactCd == "141") {
            showObj(btn_data_vf, true);
        }
    }
    scwin.fn_ChgStatComp();
    //  국채인 경우만 발행전국채거래구분코드 수정가능  jackal_150127
    scwin.fn_PresaleGovbndTrdTpCd();
    scwin.fn_list_sync();
    scwin.fn_SetDtlTab();
};
