scwin.btn_TeamleadrConfrm_onclick = function(e) {
    if (scwin.vRowCount == 0) return;
    scwin.processGp = "6";

    //체크된 것 카운팅
    var nTrueCnt = 0;
    for (var nRow = 1; nRow <= dts_List.CountRow; nRow++) {
        if (dts_List.NameString(nRow, "CHK") == "T") {
            nTrueCnt++;
        }
    }
    if (nTrueCnt == 0) {
        alert("선택된 정보가 없습니다.");
        return false;
    }

    //고객요건에의한 체크 추가. 2024-06-05 by김효준
    if (fn_AddCheck() > 0) return;
    fn_TeamleadrConfrmAll(scwin.vScrenID, trs_Save, dts_List, scwin.vBndListProcsTpCd, nTrueCnt);
};
