scwin.dts_Credit_OnLoadCompleted = function(rowcount) {
    setObjectValue(cmb_CreditValuInstCd1, '0');
    setObjectValue(cmb_ByinstCreditValuGrd1, '0');
    setObjectValue(cmb_SfValuYn1, '');
    setObjectValue(cmb_CreditValuInstCd2, '0');
    setObjectValue(cmb_ByinstCreditValuGrd2, '0');
    setObjectValue(cmb_SfValuYn2, '');
    setObjectValue(cmb_CreditValuInstCd3, '0');
    setObjectValue(cmb_ByinstCreditValuGrd3, '0');
    setObjectValue(cmb_SfValuYn3, '');
    setObjectValue(cmb_CreditValuInstCd4, '0');
    setObjectValue(cmb_ByinstCreditValuGrd4, '0');
    setObjectValue(cmb_SfValuYn4, '');
    if (rowcount > 0) {
        for (var idx = 1; idx <= rowcount; idx++) {
            if (dts_Credit.NameValue(idx, 'CREDIT_VALU_INST_CD') == '9201') {
                setObjectValue(cmb_CreditValuInstCd1, dts_Credit.NameValue(idx, "CREDIT_VALU_INST_CD"));
                setObjectValue(cmb_ByinstCreditValuGrd1, dts_Credit.NameValue(idx, "BYINST_CREDIT_VALU_GRD"));
                setObjectValue(cmb_SfValuYn1, dts_Credit.NameValue(idx, "SF_VALU_YN"));
            } else if (dts_Credit.NameValue(idx, 'CREDIT_VALU_INST_CD') == '9202') {
                setObjectValue(cmb_CreditValuInstCd2, dts_Credit.NameValue(idx, "CREDIT_VALU_INST_CD"));
                setObjectValue(cmb_ByinstCreditValuGrd2, dts_Credit.NameValue(idx, "BYINST_CREDIT_VALU_GRD"));
                setObjectValue(cmb_SfValuYn2, dts_Credit.NameValue(idx, "SF_VALU_YN"));
            } else if (dts_Credit.NameValue(idx, 'CREDIT_VALU_INST_CD') == '9203') {
                setObjectValue(cmb_CreditValuInstCd3, dts_Credit.NameValue(idx, "CREDIT_VALU_INST_CD"));
                setObjectValue(cmb_ByinstCreditValuGrd3, dts_Credit.NameValue(idx, "BYINST_CREDIT_VALU_GRD"));
                setObjectValue(cmb_SfValuYn3, dts_Credit.NameValue(idx, "SF_VALU_YN"));
            } else if (dts_Credit.NameValue(idx, 'CREDIT_VALU_INST_CD') == '9204') {
                setObjectValue(cmb_CreditValuInstCd4, dts_Credit.NameValue(idx, "CREDIT_VALU_INST_CD"));
                setObjectValue(cmb_ByinstCreditValuGrd4, dts_Credit.NameValue(idx, "BYINST_CREDIT_VALU_GRD"));
                setObjectValue(cmb_SfValuYn4, dts_Credit.NameValue(idx, "SF_VALU_YN"));
            }
        }
    }
};
