scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '1') {
        alert(getMessageParam("MSG-A002", "접수"));
    }
    if (scwin.processGp == '3') {
        alert(getMessageParam("MSG-A002", "처리완료"));
    }
    if (scwin.processGp == '4') {
        alert(getMessageParam("MSG-A002", "수정"));
    }
    if (scwin.processGp == '6') {
        alert(getMessageParam("MSG-A002", "팀장확인"));
    }
    if (scwin.processGp == '9') {
        alert(getMessageParam("MSG-A002", "표준코드요청"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '1') {
        alert(getMessageParam("MSG-A001", "접수"));
    }
    if (scwin.processGp == '3') {
        alert(getMessageParam("MSG-A001", "처리완료"));
        scwin.fn_list_sync();
    }
    if (scwin.processGp == '4') {
        alert(getMessageParam("MSG-A001", "수정"));
        scwin.fn_list_sync();
    }
    if (scwin.processGp == '6') {
        alert(getMessageParam("MSG-A001", "팀장확인"));
        scwin.fn_list_sync();
    }
    if (scwin.processGp == '9') {
        alert(getMessageParam("MSG-A001", "표준코드요청"));
    }

    //접수
    if (scwin.processGp == '1') {
        //tab_List.ActiveIndex = 2;
        scwin.fn_ClearIsuInfo();
        scwin.fn_list_sync();
    }
};
