scwin.dts_UdwrtInst_OnLoadCompleted = function(rowcount) {
    setObjectValue(cmb_BndUdwrtInstCd1, '0');
    setObjectValue(edt_UdwrtAmt1, '');
    setObjectValue(cmb_BndUdwrtInstCd2, '0');
    setObjectValue(edt_UdwrtAmt2, '');
    setObjectValue(cmb_BndUdwrtInstCd3, '0');
    setObjectValue(edt_UdwrtAmt3, '');
    setObjectValue(cmb_BndUdwrtInstCd4, '0');
    setObjectValue(edt_UdwrtAmt4, '');
    setObjectValue(edt_UdwrtAmt5, '');
    if (rowcount >= 1) {
        scwin.fn_SetUdwrtInst(1, cmb_BndUdwrtInstCd1, edt_UdwrtAmt1);
    }
    if (rowcount >= 2) {
        scwin.fn_SetUdwrtInst(2, cmb_BndUdwrtInstCd2, edt_UdwrtAmt2);
    }
    if (rowcount >= 3) {
        scwin.fn_SetUdwrtInst(3, cmb_BndUdwrtInstCd3, edt_UdwrtAmt3);
    }
    if (rowcount >= 4) {
        scwin.fn_SetUdwrtInst(4, cmb_BndUdwrtInstCd4, edt_UdwrtAmt4);
    }
    if (rowcount >= 5) {
        setObjectValue(edt_UdwrtAmt5, dts_UdwrtInst.NameValue(5, 'UDWRT_AMT'));
    }
};
scwin.dts_SecutizAsst_OnLoadCompleted = function(rowcount) {
    setObjectValue(cmb_SecutizAsstTpCd1, '0');
    setObjectValue(cmb_AsstHdTpCd1, '0');
    setObjectValue(cmb_AsstHdInstCd1, '0');
    setObjectValue(cmb_AsstAdmInstCd1, '0');
    setObjectValue(cmb_SecutizAsstTpCd2, '0');
    setObjectValue(cmb_AsstHdTpCd2, '0');
    setObjectValue(cmb_AsstHdInstCd2, '0');
    setObjectValue(cmb_AsstAdmInstCd2, '0');
    setObjectValue(cmb_SecutizAsstTpCd3, '0');
    setObjectValue(cmb_AsstHdTpCd3, '0');
    setObjectValue(cmb_AsstHdInstCd3, '0');
    setObjectValue(cmb_AsstAdmInstCd3, '0');
    setObjectValue(txb_AsstHdInstMiscContn, '');
    setObjectValue(txb_AsstHdTpMiscContn, '');
    setObjectValue(txb_AsstAdmInstMiscContn, '');
    setObjectValue(txb_SecutizAsstTpMiscContn, '');
    setObjectValue(txb_AsstHdInstMiscContn, '');
    if (rowcount > 0) {
        for (var idx = 1; idx <= rowcount; idx++) {
            if (dts_SecutizAsst.NameValue(idx, 'HD_ASST_ORD') == 1) {
                scwin.fn_SetSecutizAsstTpCd(idx, cmb_SecutizAsstTpCd1);
                scwin.fn_SetSecutizAsstHdTpCd(idx, cmb_AsstHdTpCd1, cmb_AsstHdInstCd1, cmb_AsstAdmInstCd1);
            } else if (dts_SecutizAsst.NameValue(idx, 'HD_ASST_ORD') == 2) {
                scwin.fn_SetSecutizAsstTpCd(idx, cmb_SecutizAsstTpCd2);
                scwin.fn_SetSecutizAsstHdTpCd(idx, cmb_AsstHdTpCd2, cmb_AsstHdInstCd2, cmb_AsstAdmInstCd2);
            } else if (dts_SecutizAsst.NameValue(idx, 'HD_ASST_ORD') == 3) {
                scwin.fn_SetSecutizAsstTpCd(idx, cmb_SecutizAsstTpCd3);
                scwin.fn_SetSecutizAsstHdTpCd(idx, cmb_AsstHdTpCd3, cmb_AsstHdInstCd3, cmb_AsstAdmInstCd3);
            } else if (dts_SecutizAsst.NameValue(idx, 'HD_ASST_ORD') == 4) {
                setObjectValue(txb_SecutizAsstTpMiscContn, dts_SecutizAsst.NameValue(idx, 'SECUTIZ_ASST_TP_MISC_CONTN'));
                setObjectValue(txb_AsstHdTpMiscContn, dts_SecutizAsst.NameValue(idx, 'ASST_HD_TP_MISC_CONTN'));
                setObjectValue(txb_AsstHdInstMiscContn, dts_SecutizAsst.NameValue(idx, 'ASST_HD_INST_MISC_CONTN'));
                setObjectValue(txb_AsstAdmInstMiscContn, dts_SecutizAsst.NameValue(idx, 'ASST_ADM_INST_MISC_CONTN'));
            }
        }
    }
};
