scwin.cmb_IntPayMethdCd_OnSelChange2 = function() {
    var cd = getObjectValue(cmb_IntPayMethdCd);
    //이자지급방법이 변동금리형이면
    if (cd > 20) {
        //변동금리탭 설정
        cmb_IntRtDecsnMiscBasIntCd.Enable2 = true;
        txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
        setObjectValue(cmb_IntRtDecsnMiscBasIntCd, getObjectValue(cmb_CoupnRtDecsnBasIntCd));
        if (getObjectValue(cmb_CoupnRtDecsnBasIntCd) == '90') {
            txb_CoupnRtMiscBasIntContn.setDisabled(true);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
            if (getObjectValue(txb_IntRtDecsnMiscBasIntNm) != '' &&
                getObjectValue(txb_CoupnRtMiscBasIntContn) == '') {
                setObjectValue(txb_CoupnRtMiscBasIntContn, getObjectValue(txb_IntRtDecsnMiscBasIntNm));
            } else {
                setObjectValue(txb_IntRtDecsnMiscBasIntNm, getObjectValue(txb_CoupnRtMiscBasIntContn));
            }
        } else {
            setObjectValue(txb_IntRtDecsnMiscBasIntNm, '');
            setObjectValue(txb_CoupnRtMiscBasIntContn, '');
            txb_CoupnRtMiscBasIntContn.setDisabled(false);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
        }
    } else {
        //변동금리탭 클리어
        setObjectValue(cmb_IntRtDecsnMiscBasIntCd, '');
        setObjectValue(txb_IntRtDecsnMiscBasIntNm, '');
        setObjectValue(cmb_SpdSgn, '');
        setObjectValue(edt_Spd, '');
        setObjectValue(cmb_IntRtDecsnTmCd, '');
        setObjectValue(edt_UplmtCoupnRt, '');
        setObjectValue(edt_LwlmtCoupnRt, '');
        setObjectValue(edt_IntRtDecsnBasDd, '');
        dts_ChgInt.ClearData();
        cmb_IntRtDecsnMiscBasIntCd.Enable2 = false;
        txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
        //txb_CoupnRtMiscBasIntContn.disabled = true;

        // 변동금리 추가항목 클리어 JACKAL_190509
        setObjectValue(cmb_IntDecsnRegulYn, '');
        setObjectValue(txb_IntDecsnNregulRsnContn, '');
        setObjectValue(cmb_IntDecsnBasTpCd, '');
        setObjectValue(edt_IntDecsnBasDys, '');
        setObjectValue(edt_IntPayCnt, '');
    }
};
scwin.cmb_CoupnRtDecsnBasIntCd_OnKillFocus = function(e) {
    //이자지급방법이 변동금리형
    var cd = getObjectValue(cmb_IntPayMethdCd);
    if (cd > 20) {
        //변동금리탭
        cmb_IntRtDecsnMiscBasIntCd.Enable2 = true;
        txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
        setObjectValue(cmb_IntRtDecsnMiscBasIntCd, getObjectValue(cmb_CoupnRtDecsnBasIntCd));
        //기타를 선택하면
        if (getObjectValue(cmb_CoupnRtDecsnBasIntCd) == '90') {
            txb_CoupnRtMiscBasIntContn.setDisabled(true);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
        } else {
            txb_CoupnRtMiscBasIntContn.setDisabled(false);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
            setObjectValue(txb_CoupnRtMiscBasIntContn, '');
            setObjectValue(txb_IntRtDecsnMiscBasIntNm, '');
        }
    } else {
        if (getObjectValue(cmb_CoupnRtDecsnBasIntCd) == '90') {
            txb_CoupnRtMiscBasIntContn.setDisabled(true);
        } else {
            txb_CoupnRtMiscBasIntContn.setDisabled(false);
            setObjectValue(txb_CoupnRtMiscBasIntContn, '');
        }
    }
};
