scwin.tab_Detail_OnSelChanged = function(nIndex) {
    if (scwin.vRowCount == 0) return;
    if (getObjectValue(cmb_IntPayMethdCd) > 20) {
        //표면이자율선택시 변동금리의 기타 설정
        if (nIndex == 3) {
            if (getObjectValue(cmb_IntRtDecsnMiscBasIntCd) == '90') {
                setObjectValue(txb_CoupnRtMiscBasIntContn, getObjectValue(txb_IntRtDecsnMiscBasIntNm));
            }
        }
        //변동금리선택시 표면이자율의 기타 설정
        else if (nIndex == 4) {
            if (getObjectValue(cmb_CoupnRtDecsnBasIntCd) == '90') {
                setObjectValue(txb_IntRtDecsnMiscBasIntNm, getObjectValue(txb_CoupnRtMiscBasIntContn));
            }
        }
    }
};
