scwin.txb_UnqIsuEngNm_onkeyup = function() {
    var pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    var str = getObjectValue(txb_UnqIsuEngNm) + ' ';
    for (var i = 0; i < com.wconv.length(str) - 1; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            alert('한글은 사용할 수 없습니다');
            setObjectValue(txb_UnqIsuEngNm, str.substring(0, com.wconv.length(str) - 2));
        }
    }
};
