scwin.cmb_AsstSecutizTpCd_OnSelChange2 = function() {
    if (scwin.vBndListProcsTpCd == '1') return;
    cmb_SfValuYn1.Enable2 = true;
    cmb_SfValuYn2.Enable2 = true;
    cmb_SfValuYn3.Enable2 = true;
    cmb_SfValuYn4.Enable2 = true;
    if (getObjectValue(cmb_AsstSecutizTpCd) != '') {
        if (getObjectValue(cmb_CreditValuInstCd1) != '') {
            setObjectValue(cmb_SfValuYn1, 'Y');
        }
        if (getObjectValue(cmb_CreditValuInstCd2) != '') {
            setObjectValue(cmb_SfValuYn2, 'Y');
        }
        if (getObjectValue(cmb_CreditValuInstCd3) != '') {
            setObjectValue(cmb_SfValuYn3, 'Y');
        }
        if (getObjectValue(cmb_CreditValuInstCd4) != '') {
            setObjectValue(cmb_SfValuYn4, 'Y');
        }
    } else {
        setObjectValue(cmb_SfValuYn1, '');
        setObjectValue(cmb_SfValuYn2, '');
        setObjectValue(cmb_SfValuYn3, '');
        setObjectValue(cmb_SfValuYn4, '');
        cmb_SfValuYn1.Enable2 = false;
