scwin.cmb_NusualBndTpCd_OnKillFocus = function(e) {
    //주식관련사채가 아니면 권리구분 클리어
    if (getObjectValue(cmb_NusualBndTpCd) != '2') {
        setObjectValue(cmb_StkRelCorpbndRghtTpCd, '');
    }
    //ELB/DLB 일 경우 옵션설정
    if (getObjectValue(cmb_NusualBndTpCd) == '3' ||
        getObjectValue(cmb_NusualBndTpCd) == '4') {
        var cd = '';
        if (getObjectValue(cmb_RghtTpCd) == 'C') cd = '1';

        else if (getObjectValue(cmb_RghtTpCd) == 'P') cd = '2';

        else if (getObjectValue(cmb_RghtTpCd) == 'A') cd = '3';
        setObjectValue(cmb_ImbdoptCorpbndCd, cd);
    }
};
