    }
};
scwin.dts_FrnBasIntTpCd4_OnFilter = function(row) {
    var frnBasIntTpCd1 = getObjectValue(cmb_FrnBasIntTpCd1);
    if (frnBasIntTpCd1 == "1" || frnBasIntTpCd1 == "6" || frnBasIntTpCd1 == "7") {
        return false;
    } else if (frnBasIntTpCd1 == "2" || frnBasIntTpCd1 == "3" || frnBasIntTpCd1 == "4") {
        if (com.wconv.subStr(0, 1) == "0") {
            return true;
        } else {
            return false;
        }
    } else if (frnBasIntTpCd1 == "5") {
        if (com.wconv.subStr(0, 1) == frnBasIntTpCd1) {
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
};
